int main(void) {
    int R, C;
    if (scanf("%d %d", &R, &C) != 2) return 0;

    ll **a = (ll **)malloc(sizeof(ll *) * R);
    for (int i = 0; i < R; i++) {
        a[i] = (ll *)malloc(sizeof(ll) * C);
        for (int j = 0; j < C; j++) {
            scanf("%lld", &a[i][j]);
        }
    }

    /* 
       A grid satisfies:
         x[i][j] + x[i+1][j+1] = x[i][j+1] + x[i+1][j]
       for every 2x2 square
       iff it can be written as:
         x[i][j] = r[i] + c[j]

       For given written numbers a[i][j], we need:
         a[i][j] = r[i] + c[j]
       with all filled values non-negative.
       Since all given numbers are non-negative, once such decomposition exists,
       choosing c'[j] = c[j] - min(c), r'[i] = r[i] + min(c) makes all r', c'
       non-negative, hence every cell r'[i] + c'[j] is non-negative.

       So it is enough to check consistency:
         a[i][j] - a[i][0] = a[0][j] - a[0][0]
       for all i, j
       equivalently:
         a[i][j] + a[0][0] = a[i][0] + a[0][j]
    */

    int ok = 1;
    for (int i = 0; i < R && ok; i++) {
        for (int j = 0; j < C; j++) {
            if (a[i][j] + a[0][0] != a[i][0] + a[0][j]) {
                ok = 0;
                break;
            }
        }
    }

    puts(ok ? "Yes" : "No");

    for (int i = 0; i < R; i++) free(a[i]);
    free(a);

    return 0;
}

