#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int R, C, N;
    cin >> R >> C >> N;

    // A grid satisfying
    // a[i][j] + a[i+1][j+1] = a[i][j+1] + a[i+1][j]
    // for every 2x2 block is exactly of the form:
    // a[i][j] = x[i] + y[j].
    //
    // For every given cell (r, c, v):
    // x[r] + y[c] = v.
    //
    // We build a bipartite graph:
    // row node r, column node c.
    // Edge (r, c) says y[c] = v - x[r].
    //
    // In each connected component, values are determined up to adding a constant
    // to all x and subtracting the same constant from all y.
    // After deriving one solution, we need to know whether some shift exists
    // making all x[i] >= 0 and all y[j] >= 0, because then every cell x[i]+y[j] is non-negative.

    vector<vector<pair<int,long long>>> rowAdj(R + 1), colAdj(C + 1);

    for (int i = 0; i < N; i++) {
        int r, c;
        long long v;
        cin >> r >> c >> v;
        rowAdj[r].push_back({c, v});
        colAdj[c].push_back({r, v});
    }

    const long long INF = (1LL << 60);

    vector<int> visR(R + 1, 0), visC(C + 1, 0);
    vector<long long> x(R + 1, 0), y(C + 1, 0);

    for (int sr = 1; sr <= R; sr++) {
        if (visR[sr] || rowAdj[sr].empty()) continue;

        queue<pair<int,int>> q; // {type, id}, type 0=row, 1=col
        visR[sr] = 1;
        x[sr] = 0;
        q.push({0, sr});

        long long minX = x[sr];
        long long minY = INF;

        vector<int> compRows = {sr};
        vector<int> compCols;

        while (!q.empty()) {
            auto [type, id] = q.front();
            q.pop();

            if (type == 0) {
                int r = id;
                for (auto [c, v] : rowAdj[r]) {
                    long long ny = v - x[r];
                    if (!visC[c]) {
                        visC[c] = 1;
                        y[c] = ny;
                        minY = min(minY, y[c]);
                        compCols.push_back(c);
                        q.push({1, c});
                    } else if (y[c] != ny) {
                        cout << "No\n";
                        return 0;
                    }
                }
            } else {
                int c = id;
                for (auto [r, v] : colAdj[c]) {
                    long long nx = v - y[c];
                    if (!visR[r]) {
                        visR[r] = 1;
                        x[r] = nx;
                        minX = min(minX, x[r]);
                        compRows.push_back(r);
                        q.push({0, r});
                    } else if (x[r] != nx) {
                        cout << "No\n";
                        return 0;
                    }
                }
            }
        }

        if (minY == INF) minY = 0; // component with only one isolated row and no edges can't happen here

        // Shift by t:
        // x' = x + t, y' = y - t
        // Need x' >= 0 and y' >= 0
        // => t >= -minX and t <= minY
        if (-minX > minY) {
            cout << "No\n";
            return 0;
        }
    }

    // Also need to visit components starting from columns only
    for (int sc = 1; sc <= C; sc++) {
        if (visC[sc] || colAdj[sc].empty()) continue;

        queue<pair<int,int>> q;
        visC[sc] = 1;
        y[sc] = 0;
        q.push({1, sc});

        long long minX = INF;
        long long minY = y[sc];

        vector<int> compRows;
        vector<int> compCols = {sc};

        while (!q.empty()) {
            auto [type, id] = q.front();
            q.pop();

            if (type == 0) {
                int r = id;
                for (auto [c, v] : rowAdj[r]) {
                    long long ny = v - x[r];
                    if (!visC[c]) {
                        visC[c] = 1;
                        y[c] = ny;
                        minY = min(minY, y[c]);
                        compCols.push_back(c);
                        q.push({1, c});
                    } else if (y[c] != ny) {
                        cout << "No\n";
                        return 0;
                    }
                }
            } else {
                int c = id;
                for (auto [r, v] : colAdj[c]) {
                    long long nx = v - y[c];
                    if (!visR[r]) {
                        visR[r] = 1;
                        x[r] = nx;
                        minX = min(minX, x[r]);
                        compRows.push_back(r);
                        q.push({0, r});
                    } else if (x[r] != nx) {
                        cout << "No\n";
                        return 0;
                    }
                }
            }
        }

        if (minX == INF) minX = 0;

        if (-minX > minY) {
            cout << "No\n";
            return 0;
        }
    }

    // Components with no given cells impose no restriction; fill all with 0.
    cout << "Yes\n";
    return 0;
}

