def solve():
    input_data = sys.stdin.read().split()
    idx = 0
    R, C = int(input_data[idx]), int(input_data[idx+1]); idx += 2
    grid = []
    for i in range(R):
        row = []
        for j in range(C):
            row.append(int(input_data[idx])); idx += 1
        grid.append(row)

    # -1 means unfilled
    row_val = [None] * R
    col_val = [None] * C

    queue = deque()
    for i in range(R):
        for j in range(C):
            if grid[i][j] != -1:
                queue.append((i, j, grid[i][j]))

    possible = True
    while queue and possible:
        i, j, v = queue.popleft()
        if row_val[i] is None and col_val[j] is None:
            row_val[i] = 0
            col_val[j] = v
        elif row_val[i] is not None and col_val[j] is None:
            col_val[j] = v - row_val[i]
        elif row_val[i] is None and col_val[j] is not None:
            row_val[i] = v - col_val[j]
        else:
            if row_val[i] + col_val[j] != v:
                possible = False
                break
        # propagate
        for jj in range(C):
            if grid[i][jj] != -1:
                queue.append((i, jj, grid[i][jj]))
        for ii in range(R):
            if grid[ii][j] != -1:
                queue.append((ii, j, grid[ii][j]))

    if not possible:
        print("No")
        return

    # Check non-negativity for determined pairs
    for i in range(R):
        for j in range(C):
            if row_val[i] is not None and col_val[j] is not None:
                if row_val[i] + col_val[j] < 0:
