import java.io.*;
import java.util.*;

public class Main {
    // Fast scanner
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
            } while (c != -1 && c <= ' ');
            if (c == -1) return null;
            while (c != -1 && c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        long nextLong() throws IOException {
            return Long.parseLong(next());
        }
    }

    static class DSU {
        int[] p, r;
        DSU(int n) {
            p = new int[n];
            r = new int[n];
            for (int i = 0; i < n; i++) p[i] = i;
        }
        int find(int x) {
            if (p[x] != x) p[x] = find(p[x]);
            return p[x];
        }
        void union(int a, int b) {
            a = find(a);
            b = find(b);
            if (a == b) return;
            if (r[a] < r[b]) {
                p[a] = b;
            } else if (r[a] > r[b]) {
                p[b] = a;
            } else {
                p[b] = a;
                r[a]++;
            }
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();

        int R = fs.nextInt();
        int C = fs.nextInt();

        // Input format assumed:
        // each cell is either an integer or a marker for empty.
        // We accept:
        // - "X" or "?" as empty
        // - otherwise integer
        boolean[][] known = new boolean[R][C];
        long[][] val = new long[R][C];

        for (int i = 0; i < R; i++) {
            for (int j = 0; j < C; j++) {
                String s = fs.next();
                if (s.equals("X") || s.equals("?")) {
                    known[i][j] = false;
                } else {
                    known[i][j] = true;
                    val[i][j] = Long.parseLong(s);
                }
            }
        }

        // Condition on every 2x2 implies a[i][j] = row[i] + col[j].
        // For known cells: row[i] + col[j] = val[i][j].
        //
        // Let potential on bipartite graph:
        // x_i for rows, y_j for cols.
        // Equation x_i + y_j = v.
        //
        // Build constraints x_i - x_k = v1 - v2 when sharing a column,
        // and similarly via DSU with weighted graph.
        //
        // We solve by graph traversal on bipartite graph of rows+cols:
        // node 0..R-1 = rows, R..R+C-1 = cols
        // For equation x_i + y_j = v:
        // if node values are represented as pot[node], then
        // y_j = v - x_i
        // equivalently along edge, next = v - cur.
        //
        // During DFS/BFS, each node gets affine form:
        // value(node) = sign[node] * t + bias[node], sign in {+1,-1}
        // because alternating "v - cur" flips sign.
        //
        // Then known equations inside a component may determine t or check consistency.
        // Finally need all cell values non-negative:
        // x_i + y_j >= 0 for all cells.
        // Since x_i + y_j itself is the grid value, and unknown cells also must be >= 0.
        // For each component assignment interval on t can be derived.
        // Simpler:
        // For a connected component, choose one free parameter t for one node.
        // For every row i: x_i = s_i * t + b_i
        // For every col j: y_j = s_j * t + b_j
        // Then every cell value = (s_i+s_j)t + (b_i+b_j).
        // Because rows and cols are opposite parity in a connected component, s_i+s_j = 0,
        // so within same connected component value is fixed.
        // Across different components, cells connect nothing, so if row and col are from
        // different components, value depends on two free parameters. We can choose them large
        // enough to make non-negative. Therefore only need consistency on known cells.
        //
        // More directly, the existence of a full non-negative completion is equivalent to:
        // there exist row offsets p[i], col offsets q[j] with p[i]+q[j]=known value and
        // all p[i]+q[j] >= 0 for every cell.
        //
        // After satisfying known cells, components can be shifted independently:
        // in each connected component, add d to all row variables and subtract d from all col variables.
        // This keeps known cells unchanged.
        // Need shifts so that all cross-component sums are non-negative.
        //
        // Let each row/col get base potentials from BFS. Then for a component k,
        // actual value = base + shift[k] * paritySign (rows +1, cols -1).
        // For any cell (i,j): baseRow[i]+baseCol[j] + shift[compRow]-shift[compCol] >= 0.
        // This is a system of difference constraints on component shifts.
        //
        // Components are on the bipartite known-cell graph.

        int N = R + C;
        ArrayList<int[]>[] g = new ArrayList[N];
        for (int i = 0; i < N; i++) g[i] = new ArrayList<>();

        for (int i = 0; i < R; i++) {
            for (int j = 0; j < C; j++) {
                if (known[i][j]) {
                    int u = i;
                    int v = R + j;
                    g[u].add(new int[]{v, (int)0, (int)Math.min(val[i][j], Integer.MAX_VALUE)}); // dummy third not used
                    g[v].add(new int[]{u, (int)0, (int)Math.min(val[i][j], Integer.MAX_VALUE)});
                }
            }
        }

        long[] base = new long[N];
        int[] sign = new int[N]; // +1 or -1 in affine form wrt local t
        int[] comp = new int[N];
        Arrays.fill(comp, -1);

        int compCnt = 0;
        boolean ok = true;

        for (int start = 0; start < N; start++) {
            if (comp[start] != -1) continue;

            // isolated node: arbitrary base 0, sign depends on side
            ArrayDeque<Integer> dq = new ArrayDeque<>();
            comp[start] = compCnt;
            sign[start] = (start < R ? 1 : -1);
            base[start] = 0;
            dq.add(start);

            while (!dq.isEmpty() && ok) {
                int u = dq.poll();
                if (u < R) {
                    int i = u;
                    for (int j = 0; j < C; j++) {
                        if (!known[i][j]) continue;
                        int v = R + j;
                        long expected = val[i][j] - base[u];
                        int expectedSign = -sign[u];
                        if (comp[v] == -1) {
                            comp[v] = compCnt;
                            sign[v] = expectedSign;
                            base[v] = expected;
                            dq.add(v);
                        } else {
                            if (sign[v] != expectedSign || base[v] != expected) {
                                ok = false;
                                break;
                            }
                        }
                    }
                } else {
                    int j = u - R;
                    for (int i = 0; i < R; i++) {
                        if (!known[i][j]) continue;
                        int v = i;
                        long expected = val[i][j] - base[u];
                        int expectedSign = -sign[u];
                        if (comp[v] == -1) {
                            comp[v] = compCnt;
                            sign[v] = expectedSign;
                            base[v] = expected;
                            dq.add(v);
                        } else {
                            if (sign[v] != expectedSign || base[v] != expected) {
                                ok = false;
                                break;
                            }
                        }
                    }
                }
            }

            compCnt++;
        }

        if (!ok) {
            System.out.println("No");
            return;
        }

        // Difference constraints on shifts of components:
        // For any cell (i,j):
        // (base[i] + shift[cr]) + (base[R+j] - shift[cc]) >= 0
        // => shift[cc] - shift[cr] <= base[i] + base[R+j]
        //
        // Let z[k] = shift[k].
        // Edge cr -> cc with weight baseSum means z[cc] <= z[cr] + baseSum.
        //
        // Need feasibility of all such constraints. This always exists iff no negative cycle.
        // Since there is no lower/upper bound otherwise, run Bellman-Ford/SPFA on graph with super source.

        ArrayList<int[]>[] dag = new ArrayList[compCnt];
        for (int i = 0; i < compCnt; i++) dag[i] = new ArrayList<>();

        for (int i = 0; i < R; i++) {
            for (int j = 0; j < C; j++) {
                int cr = comp[i];
                int cc = comp[R + j];
                long w = base[i] + base[R + j];
                if (cr == cc) {
                    // Then value is invariant under shift and must already be non-negative.
                    if (w < 0) {
                        System.out.println("No");
                        return;
                    }
                } else {
                    // store as long via index into arrays later
                    dag[cr].add(new int[]{cc, 0});
                    dag[cr].get(dag[cr].size() - 1)[1] = 0; // placeholder
                }
            }
        }

        // Since int[] cannot store long nicely, rebuild edges in arrays
        ArrayList<Integer> from = new ArrayList<>();
        ArrayList<Integer> to = new ArrayList<>();
        ArrayList<Long> wt = new ArrayList<>();

        for (int i = 0; i < R; i++) {
            for (int j = 0; j < C; j++) {
                int cr = comp[i];
                int cc = comp[R + j];
                long w = base[i] + base[R + j];
                if (cr != cc) {
                    from.add(cr);
                    to.add(cc);
                    wt.add(w);
                }
            }
        }

        // SPFA for negative cycle detection on constraints z[v] <= z[u] + w
        // Initialize all z = 0 with super source.
        long[] dist = new long[compCnt];
        int[] cnt = new int[compCnt];
        boolean[] inq = new boolean[compCnt];
        ArrayDeque<Integer> q = new ArrayDeque<>();
        for (int i = 0; i < compCnt; i++) {
            q.add(i);
            inq[i] = true;
        }

        // adjacency list for edges indices
        ArrayList<Integer>[] adj = new ArrayList[compCnt];
        for (int i = 0; i < compCnt; i++) adj[i] = new ArrayList<>();
        for (int e = 0; e < from.size(); e++) adj[from.get(e)].add(e);

        while (!q.isEmpty()) {
            int u = q.poll();
            inq[u] = false;
            for (int ei : adj[u]) {
                int v = to.get(ei);
                long w = wt.get(ei);
                if (dist[v] > dist[u] + w) {
                    dist[v] = dist[u] + w;
                    cnt[v] = cnt[u] + 1;
                    if (cnt[v] >= compCnt) {
                        System.out.println("No");
                        return;
                    }
                    if (!inq[v]) {
                        q.add(v);
                        inq[v] = true;
                    }
                }
            }
        }

        System.out.println("Yes");
    }
}
